export type ParsedExecuteTriggerOrderInstruction<
  TProgram extends string = typeof SOLFX_CORE_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    /** Anyone. The tip is what makes that true in practice rather than only in principle. */
    keeper: TAccountMetas[0];
    protocol: TAccountMetas[1];
    userAccount: TAccountMetas[2];
    market: TAccountMetas[3];
    position: TAccountMetas[4];
    /**
     * **Closed to the keeper — its rent is the tip.**
     *
     * The trader paid this rent when they placed the order, so the fee is pre-funded by the
     * party who wanted the order and costs the protocol nothing. It needs no token account,
     * moves no USDC, and therefore adds no term to invariant I7 — which is also why the
     * account list stays inside the BPF stack frame.
     */
    triggerOrder: TAccountMetas[5];
    collateralVault: TAccountMetas[6];
    lpPool: TAccountMetas[7];
    lpVault: TAccountMetas[8];
    insuranceFund: TAccountMetas[9];
    insuranceVault: TAccountMetas[10];
    feeVault: TAccountMetas[11];
    priceUpdate: TAccountMetas[12];
    secondaryPriceUpdate?: TAccountMetas[13] | undefined;
    quoteConversionPriceUpdate?: TAccountMetas[14] | undefined;
    tokenProgram: TAccountMetas[15];
  };
  data: ExecuteTriggerOrderInstructionData;
};

export function parseExecuteTriggerOrderInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedExecuteTriggerOrderInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 16) {
    // TODO: Coded error.
    throw new Error("Not enough accounts");
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  const getNextOptionalAccount = () => {
    const accountMeta = getNextAccount();
    return accountMeta.address === SOLFX_CORE_PROGRAM_ADDRESS
      ? undefined
      : accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      keeper: getNextAccount(),
      protocol: getNextAccount(),
      userAccount: getNextAccount(),
      market: getNextAccount(),
      position: getNextAccount(),
      triggerOrder: getNextAccount(),
      collateralVault: getNextAccount(),
      lpPool: getNextAccount(),
      lpVault: getNextAccount(),
      insuranceFund: getNextAccount(),
      insuranceVault: getNextAccount(),
      feeVault: getNextAccount(),
      priceUpdate: getNextAccount(),
      secondaryPriceUpdate: getNextOptionalAccount(),
      quoteConversionPriceUpdate: getNextOptionalAccount(),
      tokenProgram: getNextAccount(),
    },
    data: getExecuteTriggerOrderInstructionDataDecoder().decode(
      instruction.data,
    ),
  };
}
